// @ts-check
// End-to-end tests for the dashboard itself. They run against the deterministic sample
// report generated by `npm run samples`, and compute expected numbers from that file.
import { test, expect } from '@playwright/test';
import { readFileSync } from 'node:fs';

const RUN = 'run-2026-10-15-04-27';
const report = JSON.parse(readFileSync(new URL(`../storage/reports/${RUN}.json`, import.meta.url), 'utf8'));
const s = report.stats;
const total = s.expected + s.unexpected + s.flaky + s.skipped;

const rows = (page) => page.locator('.tests-table tbody tr[data-href]');
const isMobile = (testInfo) => testInfo.project.name.includes('mobile');

test.describe('Overview', () => {
  test('shows KPI totals that match the report @smoke', async ({ page }) => {
    await page.goto(`/#/overview?run=${RUN}`);
    const kpi = (label) => page.locator('.kpi').filter({ has: page.locator('.kpi-label', { hasText: new RegExp(`^${label}$`) }) }).locator('.kpi-value');
    await expect(kpi('Total tests')).toHaveText(String(total));
    await expect(kpi('Passed')).toHaveText(String(s.expected));
    await expect(kpi('Failed')).toHaveText(String(s.unexpected));
    await expect(kpi('Flaky')).toHaveText(String(s.flaky));
    await expect(kpi('Skipped')).toHaveText(String(s.skipped));
  });

  test('clicking the Failed KPI opens the filtered test list', async ({ page }) => {
    await page.goto(`/#/overview?run=${RUN}`);
    await page.locator('.kpi').filter({ has: page.locator('.kpi-label', { hasText: /^Failed$/ }) }).click();
    await expect(page).toHaveURL(/#\/tests\?.*status=failed/);
    await expect(rows(page)).toHaveCount(s.unexpected);
    for (const badge of await rows(page).locator('.badge').all()) await expect(badge).toHaveText('Failed');
  });

  test('trend chart has one point per stored run', async ({ page }) => {
    const manifest = JSON.parse(readFileSync(new URL('../storage/manifest.json', import.meta.url), 'utf8'));
    await page.goto(`/#/overview?run=${RUN}`);
    await expect(page.locator('.chart .pt')).toHaveCount(manifest.runs.length);
  });
});

test.describe('Tests view filters', () => {
  test('status chips combine and are reflected in the URL @smoke', async ({ page }) => {
    await page.goto(`/#/tests?run=${RUN}`);
    await expect(rows(page)).toHaveCount(total);
    await page.locator('.chip.failed').click();
    await page.locator('.chip.flaky').click();
    await expect(rows(page)).toHaveCount(s.unexpected + s.flaky);
    await expect(page).toHaveURL(/status=failed%2Cflaky|status=failed,flaky/);
    await page.getByRole('button', { name: 'Clear all' }).click();
    await expect(rows(page)).toHaveCount(total);
  });

  test('search narrows results and survives a reload', async ({ page }) => {
    await page.goto(`/#/tests?run=${RUN}`);
    await page.getByLabel('Search tests').fill('transfer');
    await expect(page.getByText(/Showing \d+ of \d+ \(\d+ total\)/)).not.toContainText(`of ${total} (`);
    const n = await rows(page).count();
    expect(n).toBeGreaterThan(0);
    expect(n).toBeLessThan(total);
    for (const title of await rows(page).locator('.t-title').allTextContents()) expect(title.toLowerCase()).toContain('transfer');
    await page.reload();
    await expect(page.getByLabel('Search tests')).toHaveValue('transfer');
    await expect(rows(page)).toHaveCount(n);
  });

  test('project and tag selects filter the table', async ({ page }) => {
    await page.goto(`/#/tests?run=${RUN}`);
    await page.getByLabel('Project').selectOption('webkit');
    await expect(rows(page)).toHaveCount(total / 3);
    await page.getByLabel('Tag').selectOption('api');
    await expect(rows(page)).toHaveCount(3);
  });

  test('sidebar file tree filters by spec file', async ({ page }, testInfo) => {
    await page.goto(`/#/tests?run=${RUN}`);
    if (isMobile(testInfo)) await page.getByLabel('Toggle navigation').click();
    await page.locator('.tree-file', { hasText: 'login.spec.ts' }).click();
    await expect(page).toHaveURL(/file=auth%2Flogin\.spec\.ts/);
    await expect(rows(page)).toHaveCount(15);
    for (const p of await rows(page).locator('.t-path').allTextContents()) expect(p).toContain('auth/login.spec.ts');
  });

  test('sorting by duration puts the slowest test first', async ({ page }) => {
    await page.goto(`/#/tests?run=${RUN}&sort=duration&dir=desc`);
    const durations = await rows(page).locator('td.num').last().allTextContents();
    expect(durations.length).toBeGreaterThan(0);
    await expect(page.locator('th button[aria-sort="descending"]')).toContainText('Duration');
  });
});

test.describe('Test detail', () => {
  test('shows the error, steps and retries of a failed test @smoke', async ({ page }) => {
    await page.goto(`/#/tests?run=${RUN}&status=failed`);
    await rows(page).first().click();
    await expect(page).toHaveURL(/#\/test\//);
    await expect(page.locator('.detail-head .badge')).toHaveText('Failed');
    await expect(page.locator('#attempt pre.code').first()).toBeVisible();
    await expect(page.locator('.steps .step').first()).toBeVisible();
    await expect(page.getByRole('tab')).toHaveCount(2);
    await page.getByRole('tab', { name: /Retry #1/ }).click();
    await expect(page.getByRole('tab', { name: /Retry #1/ })).toHaveAttribute('aria-selected', 'true');
    await expect(page.locator('.history a').first()).toBeVisible();
  });

  test('j/k move through the filtered list and back restores filters', async ({ page }, testInfo) => {
    test.skip(isMobile(testInfo), 'keyboard shortcuts are a desktop feature');
    await page.goto(`/#/tests?run=${RUN}&status=flaky`);
    await rows(page).first().click();
    await expect(page.getByText(`1 of ${s.flaky} in the current filter`)).toBeVisible();
    await page.keyboard.press('j');
    await expect(page.getByText(`2 of ${s.flaky} in the current filter`)).toBeVisible();
    await page.getByRole('link', { name: '← Tests' }).click();
    await expect(rows(page)).toHaveCount(s.flaky);
  });
});

test.describe('Runs & navigation', () => {
  test('run picker switches the active report', async ({ page }) => {
    await page.goto(`/#/overview?run=${RUN}`);
    const other = await page.locator('#run-select option').nth(1).getAttribute('value');
    test.skip(!other || other === RUN, 'needs at least two runs');
    await page.locator('#run-select').selectOption(other);
    await expect(page).toHaveURL(new RegExp(`run=${other}`));
  });

  test('runs view lists every run and the least stable tests', async ({ page }) => {
    await page.goto(`/#/runs?run=${RUN}`);
    await expect(page.getByRole('heading', { name: 'Least stable tests' })).toBeVisible();
    await expect(page.locator('#unstable tbody tr').first()).toBeVisible();
  });

  test('a report can be loaded from disk', async ({ page }) => {
    await page.goto(`/#/overview?run=${RUN}`);
    await page.locator('#file-input').setInputFiles({
      name: 'my-results.json',
      mimeType: 'application/json',
      buffer: Buffer.from(JSON.stringify(report)),
    });
    await expect(page).toHaveURL(/run=local-/);
    await expect(page.locator('#run-select')).toContainText('my-results.json');
    await expect(page.locator('.kpi', { hasText: 'Total tests' }).locator('.kpi-value')).toHaveText(String(total));
  });

  test('an invalid file shows an error instead of breaking the page', async ({ page }) => {
    await page.goto(`/#/overview?run=${RUN}`);
    await page.locator('#file-input').setInputFiles({ name: 'oops.json', mimeType: 'application/json', buffer: Buffer.from('{"not":"a report"}') });
    await expect(page.locator('#toast')).toContainText('not a Playwright JSON report');
    await expect(page.locator('.kpis')).toBeVisible();
  });

  test('the page has no horizontal scroll', async ({ page }) => {
    for (const view of ['overview', 'tests', 'runs']) {
      await page.goto(`/#/${view}?run=${RUN}`);
      await page.waitForSelector('.view-head');
      const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
      expect(overflow, `${view} overflows`).toBeLessThanOrEqual(0);
    }
  });
});
